        }
      ],
      "anchors": [
        {
          "line_start": 197,
          "line_end": 202,
          "support": "Defines L(P,omega) as the on-site Green's function with integral over BZ^(2), and states Im[L] is proportional to total density of on-shell states and Re[L] represents off-shell density."
